// ZeroNote 崩溃日志插件 —— 构建脚本。
//
// 与 `tauri-plugin-statusbar` 同构：
//   ① 按 COMMANDS 生成 `permissions/autogenerated/`（`read_last_crash` → `allow-read-last-crash`）
//   ② `.android_path("android")` 让 Tauri CLI 把本插件的 Android 库模块写进
//      `gen/android/tauri.settings.gradle`，**不用手改 gradle**。
const COMMANDS: &[&str] = &["read_last_crash"];

fn main() {
  tauri_plugin::Builder::new(COMMANDS)
    .android_path("android")
    .build();
}
